      "content": "name: Build site from README\n\non:\n  push:\n    branches: [main]\n    paths: ['README.md', 'README.en.md', 'scripts/build-site.mjs', 'scripts/probe-npm.mjs', 'scripts/probe-stars.mjs', 'site/template.html', 'site/locales.mjs']\n  schedule:\n    - cron: '17 */6 * * *'\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - name: Probe npm packages + GitHub stars\n        run: |\n          node scripts/probe-npm.mjs\n          node scripts/probe-stars.mjs\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n      - name: Build site rows from READMEs\n        run: node scripts/build-site.mjs\n      - name: Commit if changed\n        run: |\n          git config user.name \"github-actions[bot]\"\n          git config user.email \"github-actions[bot]@users.noreply.github.com\"\n          git add docs README.md README.en.md data\n          git diff --cached --quiet && echo \"no changes\" && exit 0\n          git commit -m \"chore: rebuild site from README\"\n          git push\n"
